/*
 MFA Enrolment System
 Requirements 1–5: server-owned sessions, CSRF, TLS, secure headers,
 encrypted TOTP seeds, hashed recovery codes, authorization, and rate limits.
*/

const CERT_PATH = "certs/cert.pem";
const KEY_PATH = "certs/key.pem";
const TRUSTED_ORIGINS = new Set([
  "https://localhost:3000",
  "https://127.0.0.1:3000",
  "https://[::1]:3000",
]);

const account = { id: "acct_marcus_001", name: "Marcus" };

/*
 Task: deterministic mock login credential. It is checked only by the server.
 It is never logged, returned by an API, placed in a URL, or included in errors.
*/
const TEST_LOGIN_EMAIL = "marcus@example.test";
const TEST_LOGIN_PASSWORD = "Marcus-54";

/*
 A pre-authenticated session has passed mock login but is not yet an owner
 session. /api/proof endpoints require this exact account-bound state.
*/
const authenticatedOwnerFixture = {
  accountId: account.id,
  enabled: true,
  serverAssertion: token(32),
};

type Session = {
  id: string;
  csrf: string;
  userId: string | null;
  preAuthUserId: string | null;
  proofStarted: boolean;
  fixtureAssertion: string | null;
  createdAt: number;
  lastSeenAt: number;
  expiresAt: number;
};

type AttemptState = { failures: number; lockedUntil: number };

type MfaRecord = {
  encryptedSecret: string;
  enabled: boolean;
  usedSteps: Set<number>;
  failedAttempts: number;
  lockedUntil: number;
  recoveryHashes: Set<string>;
  recoveryGenerated: boolean;
  recoveryFailedAttempts: number;
  recoveryLockedUntil: number;
  mfaVerifiedAt: number;
};

const sessions = new Map<string, Session>();
const mfaRecords = new Map<string, MfaRecord>();
const proofAttempts = new Map<string, AttemptState>();
const loginAttempts = new Map<string, AttemptState>();

const encoder = new TextEncoder();
const encryptionKey = crypto.getRandomValues(new Uint8Array(32));
const recoveryPepper = crypto.getRandomValues(new Uint8Array(32));

const SESSION_IDLE_MS = 20 * 60 * 1000;
const SESSION_ABSOLUTE_MS = 8 * 60 * 60 * 1000;
const LOCK_MS = 10 * 60 * 1000;
const MAX_FAILURES = 5;
const TOTP_PERIOD_MS = 30_000;
const RECENT_AUTH_MS = 5 * 60 * 1000;

const TRUSTED_PROXY = false;
let server: any;

function b64(bytes: Uint8Array): string {
  let value = "";
