  const current = Math.floor(Date.now() / TOTP_PERIOD_MS);
  for (const step of [current, current - 1]) {
    if (!record.usedSteps.has(step) && fixedTimeEqual(await totp(secret, step), code)) {
      record.usedSteps.add(step);
