   Task: anonymous callers get bootstrap/CSRF data only. MFA state is emitted
   solely once the server has confirmed the authenticated owner session.
  */
  if (path === "/api/session" && request.method === "GET") {
    let session = sessionFor(request);
    let setCookie: string | undefined;
    if (!session) {
      session = newSession();
      setCookie = cookie(session);
    }
    if (session.userId !== account.id) {
      return json({
        ok: true,
        csrf: session.csrf,
        authenticated: false,
        preAuthenticated: session.preAuthUserId === account.id,
      }, 200, setCookie ? { "Set-Cookie": setCookie } : undefined);
