    const record = mfaRecords.get(account.id);
    return json({
      ok: true,
      csrf: session.csrf,
      authenticated: true,
      mfaEnabled: !!record?.enabled,
      recoveryGenerated: !!record?.recoveryGenerated,
    }, 200, setCookie ? { "Set-Cookie": setCookie } : undefined);
