    const email = typeof input?.email === "string" ? input.email.trim().toLowerCase() : "";
    const password = typeof input?.password === "string" ? input.password : "";
    const valid = validEmail(email) && validPassword(password) &&
      fixedTimeEqual(email, TEST_LOGIN_EMAIL) && fixedTimeEqual(password, TEST_LOGIN_PASSWORD);
    if (!valid) {
      return failedAttempt(loginAttempts, key, "sign-in", "We could not sign you in. Check your details and try again.");
