 const finder=(r,c)=>{for(let y=-1;y<=7;y++)for(let x=-1;x<=7;x++)put(r+y,c+x,y>=0&&y<=6&&x>=0&&x<=6&&(y===0||y===6||x===0||x===6||(y>=2&&y<=4&&x>=2&&x<=4)))};
 finder(0,0);finder(0,n-7);finder(n-7,0);
 for(let i=8;i<n-8;i++){put(6,i,i%2===0);put(i,6,i%2===0)}
 for(const r of [6,28,50])for(const c of [6,28,50])if(!((r===6&&c===6)||(r===6&&c===50)||(r===50&&c===6)))for(let y=-2;y<=2;y++)for(let x=-2;x<=2;x++)put(r+y,c+x,Math.max(Math.abs(x),Math.abs(y))!==1);
 for(let i=0;i<9;i++){if(a[i][8]===null)put(i,8,false);if(a[8][i]===null)put(8,i,false);if(a[n-1-i][8]===null)put(n-1-i,8,false);if(a[8][n-1-i]===null)put(8,n-1-i,false)}
 put(n-8,8,true);
 const bytes=Array.from(new TextEncoder().encode(text));if(bytes.length>271)throw new Error("QR data too long");
 const bits=[];const add=(v,len)=>{for(let i=len-1;i>=0;i--)bits.push((v>>>i)&1)};add(4,4);add(bytes.length,16);bytes.forEach(v=>add(v,8));for(let i=0;i<Math.min(4,274*8-bits.length);i++)bits.push(0);while(bits.length%8)bits.push(0);
