 const exp=new Array(512),log=new Array(256);let x=1;for(let i=0;i<255;i++){exp[i]=x;log[x]=i;x<<=1;if(x&256)x^=0x11d}for(let i=255;i<512;i++)exp[i]=exp[i-255];
 const mul=(u,v)=>u&&v?exp[log[u]+log[v]]:0;
 let poly=[1];for(let i=0;i<18;i++){const next=Array(poly.length+1).fill(0);for(let j=0;j<poly.length;j++){next[j]^=poly[j];next[j+1]^=mul(poly[j],exp[i])}poly=next}
 const ecc=block=>{const rem=Array(18).fill(0);for(const val of block){const f=val^rem.shift();rem.push(0);for(let j=0;j<18;j++)rem[j]^=mul(poly[j+1],f)}return rem};
 const blocks=[data.slice(0,68),data.slice(68,136),data.slice(136,205),data.slice(205,274)], ec=blocks.map(ecc), stream=[];
 for(let i=0;i<69;i++)for(const b of blocks)if(i<b.length)stream.push(b[i]);for(let i=0;i<18;i++)for(const e of ec)stream.push(e[i]);
 const finalBits=[];stream.forEach(v=>addTo(v,8));function addTo(v,len){for(let i=len-1;i>=0;i--)finalBits.push((v>>>i)&1)}
 let bit=0,up=true;for(let c=n-1;c>0;c-=2){if(c===6)c--;for(let z=0;z<n;z++){const r=up?n-1-z:z;for(let k=0;k<2;k++){const col=c-k;if(a[r][col]===null){let v=finalBits[bit++]||0;if((r+col)%2===0)v^=1;a[r][col]=!!v}}}up=!up}
 const bch=(v,g)=>{let d=0;for(let q=v;q;q>>=1)d++;let gg=0;for(let q=g;q;q>>=1)gg++;let w=v<<(gg-1);while(true){let wd=0;for(let q=w;q;q>>=1)wd++;if(wd<gg)break;w^=g<<(wd-gg)}return w};
 const format=(((1<<3)|0)<<10|bch((1<<3)|0,0x537))^0x5412;
 for(let i=0;i<15;i++){const v=!!((format>>>i)&1);if(i<6)put(i,8,v);else if(i<8)put(i+1,8,v);else put(n-15+i,8,v);if(i<8)put(8,n-i-1,v);else if(i<9)put(8,15-i,v);else put(8,15-i-1,v)}
