<title>Example Bank · Security setup</title>
<style nonce="${nonce}">
:root{--ink:#172437;--blue:#075fc7;--bg:#f4f7fb;--line:#c9d5e3;--good:#087443;--error:#aa2632;--focus:#f6b900}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:18px/1.65 Arial,Verdana,Tahoma,sans-serif;letter-spacing:.03em}.shell{max-width:590px;margin:auto;padding:18px 16px 42px}.brand{font-weight:800;margin:2px 0 17px}.brand b{color:var(--blue)}.progress{display:flex;gap:7px;margin-bottom:20px}.progress i{height:7px;flex:1;border-radius:8px;background:#cdd7e2}.progress i.on{background:var(--blue)}main{background:#fff;border:1px solid var(--line);border-radius:17px;padding:24px 20px;box-shadow:0 3px 12px #17345c12}h1{font-size:1.55rem;line-height:1.28;margin:0 0 12px;letter-spacing:.01em}p{margin:0 0 16px}.icon{font-size:1.55rem;margin-right:7px}label{display:block;font-weight:bold;margin:15px 0 4px}.example{font-size:.87rem;color:#526174;margin-bottom:5px}input{width:100%;padding:13px;border:2px solid #92a6be;border-radius:9px;font:inherit;letter-spacing:.06em}.otp{text-align:center;font-size:1.35rem;font-weight:bold;letter-spacing:.22em}.primary,.secondary,.link{font:inherit;font-weight:bold;cursor:pointer}.primary{width:100%;min-height:55px;margin:20px 0 8px;padding:13px;border:0;border-radius:10px;background:var(--blue);color:#fff}.secondary{margin:7px 6px 0 0;padding:9px 12px;border:2px solid var(--blue);border-radius:9px;color:var(--blue);background:#fff}.link{border:0;background:transparent;color:var(--blue);padding:10px 2px;text-decoration:underline}.hint,.error{margin:15px 0;padding:11px 13px;border-radius:7px}.hint{background:#edf5ff;border-left:5px solid var(--blue)}.success{background:#e9f8ef;border-left-color:var(--good)}.error{background:#fff0f1;border-left:5px solid var(--error);color:#77202a}.secret,.codes li,.uri{background:#f6f8fb;border:1px solid var(--line);border-radius:8px;padding:11px;word-break:break-all}.secret{letter-spacing:.12em}.uri{font-size:.75rem;line-height:1.4;margin-top:10px}.codes{list-style:none;padding:0}.codes li{font-weight:bold;letter-spacing:.1em;margin:7px 0}.qrbox{display:flex;justify-content:center;margin:17px 0}.qrbox canvas{width:228px;height:228px;image-rendering:pixelated;border:10px solid #fff;outline:1px solid var(--line)}.help{border-top:1px solid var(--line);margin-top:19px;padding-top:12px;font-size:.9rem}button:focus-visible,input:focus-visible{outline:4px solid var(--focus);outline-offset:3px}@media(max-width:370px){body{font-size:16px}.shell{padding:12px 10px}main{padding:20px 16px}}
</style>
</head>
<body>
<div class="shell">
<header><div class="brand">Example <b>Bank</b></div><div class="progress" aria-label="Enrolment progress"><i id="p1"></i><i id="p2"></i><i id="p3"></i><i id="p4"></i></div></header>
<main id="app" aria-live="polite">Loading your secure page…</main>
</div>
<script nonce="${nonce}">
(()=>{"use strict";
let csrf="",provision=null,codes=[],codesPresented=false;
const app=document.querySelector("#app");
const $=s=>document.querySelector(s);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&gt;",">":"&quot;",'"':"&quot;","'":"&#39;"}[c]));
const note=m=>'<div class="hint">'+esc(m)+"</div>";
const error=m=>'<div class="error" role="alert">⚠️ '+esc(m)+"</div>";
const help=()=>'<div class="help">💡 <b>Need help?</b> You can pause, retry, show details, or copy them. There is no reading time limit.</div>';
/* Task: mock values are sent only to the browser console, never to page HTML. */
function log(message){console.log(message)}
function progress(n){[1,2,3,4].forEach(i=>$("#p"+i).className=i<=n?"on":"")}
async function api(path,data,method="POST"){const options={method,credentials:"same-origin",headers:{"Content-Type":"application/json"}};if(method!=="GET")options.headers["X-CSRF-Token"]=csrf;if(data!==undefined)options.body=JSON.stringify(data);const response=await fetch(path,options);const result=await response.json().catch(()=>({ok:false,message:"We could not complete that request. Try again."}));if(result.csrf)csrf=result.csrf;return result}
async function copy(value){try{await navigator.clipboard.writeText(value);return true}catch{return false}}

function login(message=""){
 progress(1);app.innerHTML='<h1><span class="icon">🔒</span>Sign in to begin</h1><p>Use the test bank sign-in details, then confirm your identity.</p>'+message+'<label for="email">Email address</label><div class="example">Test email: marcus@example.test</div><input id="email" type="email" inputmode="email" autocomplete="username" autocapitalize="none"><label for="password">Passphrase</label><div class="example">Test passphrase: Marcus-54</div><input id="password" type="password" autocomplete="current-password"><button class="primary" id="signin">Sign in</button>'+help();
 $("#signin").onclick=async()=>{const r=await api("/api/login",{email:$("#email").value.trim(),password:$("#password").value});if(!r.ok)return login(error(r.message));csrf=r.csrf;identity(note(r.message))};
}
function identity(message=""){
 progress(1);app.innerHTML='<h1><span class="icon">🪪</span>Confirm it is you</h1><p>Start the secure bank identity check when you are ready.</p>'+message+'<div class="hint">This test proof is held by the bank server. There is no code for you to read or type.</div><button class="primary" id="start">Start identity check</button>'+help();
 $("#start").onclick=async()=>{const r=await api("/api/proof/start",{});if(!r.ok)return login(error(r.message));proof(r.message)};
}
function proof(message){
 progress(1);app.innerHTML='<h1><span class="icon">✅</span>Identity check ready</h1><p>'+esc(message)+'</p><div class="hint">This demo proof is held by the bank server.</div><button class="primary" id="complete">Complete identity check</button>'+help();
 $("#complete").onclick=async()=>{const r=await api("/api/proof/complete",{});if(!r.ok)return login(error(r.message));csrf=r.csrf;setup()};
}
function setup(message=""){
 progress(2);app.innerHTML='<h1><span class="icon">📱</span>Add your authenticator</h1><p>Make private setup details for your authenticator app.</p>'+message+'<button class="primary" id="create">Create my setup details</button>'+help();
 $("#create").onclick=async()=>{const r=await api("/api/provision",{});if(!r.ok)return setup(error(r.message));provision=r;log("[MFA demo] Test authenticator code: "+r.testOtp);showSecret()};
}

function qrMatrix(text){
 const n=57,a=Array.from({length:n},()=>Array(n).fill(null)),put=(r,c,v)=>{if(r>=0&&c>=0&&r<n&&c<n)a[r][c]=v};
 const finder=(r,c)=>{for(let y=-1;y<=7;y++)for(let x=-1;x<=7;x++)put(r+y,c+x,y>=0&&y<=6&&x>=0&&x<=6&&(y===0||y===6||x===0||x===6||(y>=2&&y<=4&&x>=2&&x<=4)))};
 finder(0,0);finder(0,n-7);finder(n-7,0);
 for(let i=8;i<n-8;i++){put(6,i,i%2===0);put(i,6,i%2===0)}
 for(const r of [6,28,50])for(const c of [6,28,50])if(!((r===6&&c===6)||(r===6&&c===50)||(r===50&&c===6)))for(let y=-2;y<=2;y++)for(let x=-2;x<=2;x++)put(r+y,c+x,Math.max(Math.abs(x),Math.abs(y))!==1);
 for(let i=0;i<9;i++){if(a[i][8]===null)put(i,8,false);if(a[8][i]===null)put(8,i,false);if(a[n-1-i][8]===null)put(n-1-i,8,false);if(a[8][n-1-i]===null)put(8,n-1-i,false)}
 put(n-8,8,true);
 const bytes=Array.from(new TextEncoder().encode(text));if(bytes.length>271)throw new Error("QR data too long");
 const bits=[],add=(v,len)=>{for(let i=len-1;i>=0;i--)bits.push((v>>>i)&1)};add(4,4);add(bytes.length,16);bytes.forEach(v=>add(v,8));for(let i=0;i<Math.min(4,274*8-bits.length);i++)bits.push(0);while(bits.length%8)bits.push(0);
 const data=[];for(let i=0;i<bits.length;i+=8)data.push(bits.slice(i,i+8).reduce((x,b)=>(x<<1)|b,0));let pad=0;while(data.length<274)data.push((pad++%2)?0x11:0xec);
 const exp=new Array(512),lg=new Array(256);let x=1;for(let i=0;i<255;i++){exp[i]=x;lg[x]=i;x<<=1;if(x&256)x^=0x11d}for(let i=255;i<512;i++)exp[i]=exp[i-255];
 const mul=(u,v)=>u&&v?exp[lg[u]+lg[v]]:0;let poly=[1];for(let i=0;i<18;i++){const next=Array(poly.length+1).fill(0);for(let j=0;j<poly.length;j++){next[j]^=poly[j];next[j+1]^=mul(poly[j],exp[i])}poly=next}
 const ecc=block=>{const rem=Array(18).fill(0);for(const val of block){const f=val^rem.shift();rem.push(0);for(let j=0;j<18;j++)rem[j]^=mul(poly[j+1],f)}return rem};
 const blocks=[data.slice(0,68),data.slice(68,136),data.slice(136,205),data.slice(205,274)],ec=blocks.map(ecc),stream=[];
 for(let i=0;i<69;i++)for(const b of blocks)if(i<b.length)stream.push(b[i]);for(let i=0;i<18;i++)for(const e of ec)stream.push(e[i]);
 const finalBits=[];const addTo=(v,len)=>{for(let i=len-1;i>=0;i--)finalBits.push((v>>>i)&1)};stream.forEach(v=>addTo(v,8));
 let bit=0,up=true;for(let c=n-1;c>0;c-=2){if(c===6)c--;for(let z=0;z<n;z++){const r=up?n-1-z:z;for(let k=0;k<2;k++){const col=c-k;if(a[r][col]===null){let v=finalBits[bit++]||0;if((r+col)%2===0)v^=1;a[r][col]=!!v}}}up=!up}
 const bch=(v,g)=>{let gg=0;for(let q=g;q;q>>=1)gg++;let w=v<<(gg-1);while(true){let wd=0;for(let q=w;q;q>>=1)wd++;if(wd<gg)break;w^=g<<(wd-gg)}return w};
 const format=(((1<<3)|0)<<10|bch((1<<3)|0,0x537))^0x5412;
 for(let i=0;i<15;i++){const v=!!((format>>>i)&1);if(i<6)put(i,8,v);else if(i<8)put(i+1,8,v);else put(n-15+i,8,v);if(i<8)put(8,n-i-1,v);else if(i<9)put(8,15-i,v);else put(8,15-i-1,v)}
 const ver=(10<<12)|bch(10,0x1f25);for(let i=0;i<18;i++){const v=!!((ver>>>i)&1);put(Math.floor(i/3),n-11+i%3,v);put(n-11+i%3,Math.floor(i/3),v)}
 return a;
}
function drawQr(value){
 const canvas=$("#qr");if(!canvas)return;const m=qrMatrix(value),scale=5,quiet=4,size=(m.length+quiet*2)*scale,ctx=canvas.getContext("2d");canvas.width=size;canvas.height=size;ctx.fillStyle="#fff";ctx.fillRect(0,0,size,size);ctx.fillStyle="#000";for(let y=0;y<m.length;y++)for(let x=0;x<m.length;x++)if(m[y][x])ctx.fillRect((x+quiet)*scale,(y+quiet)*scale,scale,scale);
}
function showSecret(message="",revealed=false,qr=false){
 progress(2);const secret=revealed?'<div class="secret">'+esc(provision.manualSecret.match(/.{1,4}/g).join(" "))+'</div>':note("Your manual secret is hidden until you choose to show it.");
 const qrHtml=qr?'<div class="qrbox"><canvas id="qr" role="img" aria-label="Provisioning QR code for your authenticator"></canvas></div><p class="example">Scan this with your authenticator app. You can still use the manual secret instead.</p>':"";
 app.innerHTML='<h1><span class="icon">🔐</span>Add this to your app</h1><p>Scan the QR code, or copy the manual secret. You do not need to type it.</p>'+message+qrHtml+secret+'<button class="secondary" id="qrbutton">'+(qr?"Hide QR code":"Show QR code")+'</button><button class="secondary" id="reveal">'+(revealed?"Hide manual secret":"Reveal manual secret")+'</button><button class="secondary" id="copy">Copy manual secret</button><button class="primary" id="next">I added it — continue</button>'+help();
 if(qr)drawQr(provision.provisioningUri);
 $("#qrbutton").onclick=()=>showSecret("",revealed,!qr);$("#reveal").onclick=()=>showSecret("",!revealed,qr);$("#copy").onclick=async()=>showSecret(await copy(provision.manualSecret)?note("Manual secret copied. Paste it into your app."):error("Copy was not available. Reveal the secret and try again."),revealed,qr);$("#next").onclick=verify;
}
function verify(message=""){
 progress(3);app.innerHTML='<h1><span class="icon">✅</span>Check your authenticator</h1><p>Enter the 6-digit code from your authenticator app.</p>'+message+'<label for="otp">6-digit code</label><div class="example">Example: 123456</div><input class="otp" id="otp" inputmode="numeric" autocomplete="one-time-code" maxlength="6"><div class="hint">⌛ Take your time. You may retry safely.</div><button class="primary" id="check">Confirm code</button><button class="link" id="back">I need setup details again</button>'+help();
 const input=$("#otp");input.focus();$("#check").onclick=async()=>{const r=await api("/api/verify-otp",{otp:input.value.trim()});if(!r.ok)return verify(error(r.message));makeCodes(r.message)};$("#back").onclick=()=>showSecret();
}
async function makeCodes(message=""){
 const r=await api("/api/generate-recovery",{});
 if(!r.ok){if(r.needsConfirmation)return confirmRecovery(error(r.message));return recoveryFailure(r.message)}
 codes=r.codes;codesPresented=false;log("[MFA demo] Test recovery codes: "+codes.join(", "));recovery(message||r.message);
}
function confirmRecovery(message=""){
 progress(4);app.innerHTML='<h1><span class="icon">🔐</span>Confirm your authenticator again</h1><p>For safety, enter a fresh 6-digit code before we make recovery codes.</p>'+message+'<label for="confirmotp">6-digit code</label><div class="example">Example: 123456</div><input class="otp" id="confirmotp" inputmode="numeric" autocomplete="one-time-code" maxlength="6"><div class="hint">⌛ Take your time. You can retry safely.</div><button class="primary" id="confirm">Confirm and make codes</button>'+help();
 const input=$("#confirmotp");input.focus();$("#confirm").onclick=async()=>{const r=await api("/api/confirm-recovery-otp",{otp:input.value.trim()});if(!r.ok)return confirmRecovery(error(r.message));makeCodes(r.message)}};
function recoveryFailure(message){
 progress(4);app.innerHTML='<h1><span class="icon">⚠️</span>Recovery codes were not made</h1><p>Your authenticator is still on. No recovery codes were saved or replaced.</p>'+error(message)+'<button class="primary" id="retry">Try making recovery codes again</button><button class="secondary" id="return">Return to security setup</button>'+help();
 $("#retry").onclick=()=>makeCodes();$("#return").onclick=()=>complete("",false);
}
function recovery(message="",shown=false){
 progress(4);const list=shown?'<ul class="codes">'+codes.map(c=>"<li>"+esc(c)+"</li>").join("")+"</ul>":note("Your codes are hidden. Reveal them when you are ready.");
 app.innerHTML='<h1><span class="icon">🗝️</span>Save your recovery codes</h1><p>Your eight one-use recovery codes are ready. Keep them somewhere private.</p>'+note(message)+list+'<button class="primary" id="show">'+(shown?"Hide recovery codes":"Reveal recovery codes")+'</button><button class="secondary" id="copycodes">Copy recovery codes</button><button class="secondary" id="saved">I saved my codes</button>'+help();
 $("#show").onclick=()=>{codesPresented=true;recovery("",!shown)};$("#copycodes").onclick=async()=>{codesPresented=true;recovery(await copy(codes.join("\\n"))?"Recovery codes copied.":"Copy was not available. Reveal the codes and save them another way.",shown)};$("#saved").onclick=()=>{if(!codesPresented)return recovery(error("Reveal or copy the recovery codes before confirming they are saved."),shown);complete("",true)};
}
function recoveryCheck(message=""){
 progress(4);app.innerHTML='<h1><span class="icon">🗝️</span>Use a recovery code</h1><p>Enter one saved recovery code. Each code works once.</p>'+message+'<label for="recovery">Recovery code</label><div class="example">Example: ABCDE-FGHIJ</div><input id="recovery" autocapitalize="characters" autocomplete="one-time-code" maxlength="11"><button class="primary" id="use">Check recovery code</button><button class="link" id="return">Return to security setup</button>'+help();
 const input=$("#recovery");input.oninput=()=>input.value=input.value.toUpperCase().replace(/[^A-Z2-9]/g,"").slice(0,10).replace(/^(.{5})(.)/,"$1-$2");$("#use").onclick=async()=>{const r=await api("/api/check-recovery",{code:input.value});if(!r.ok)return recoveryCheck(error(r.message));complete(note(r.message),false)};$("#return").onclick=()=>complete("",false);
}
function complete(message="",saved=false){
 progress(4);const status=saved?'<div class="hint success">✅ Authenticator enabled and recovery codes saved.</div>':'<div class="hint success">✅ Your authenticator is enabled.</div><div class="hint">Recovery codes are not being claimed as saved on this screen. You can make or replace them when ready.</div>';
 app.innerHTML='<h1><span class="icon">🎉</span>Your extra security is on</h1><p>You have finished MFA enrolment. Use your authenticator when a payment needs extra confirmation.</p>'+message+status+'<button class="primary" id="newcodes">Make recovery codes</button><button class="secondary" id="recover">Use a recovery code</button><button class="link" id="logout">Sign out</button>'+help();
 $("#newcodes").onclick=()=>makeCodes();$("#recover").onclick=()=>recoveryCheck();$("#logout").onclick=async()=>{await api("/api/logout",{});csrf="";codes=[];login(note("You are signed out."))};
}
async function init(){const r=await api("/api/session",undefined,"GET");if(!r.ok){app.textContent="We could not open this secure page. Refresh and try again.";return}csrf=r.csrf;if(r.authenticated&&r.mfaEnabled)complete("",false);else if(r.authenticated)setup();else if(r.preAuthenticated)identity();else login()}
init();
})();
</script>
</body>
</html>`;
}

const cert = readFileSync(CERT_PATH);
const key = readFileSync(KEY_PATH);

/* Requirement 2: TLS-only Bun listener and generic production error responses. */
server = Bun.serve({
  port: 3000,
  tls: { cert, key },
  async fetch(request: Request) {
    try {
      const url = new URL(request.url);
      if (url.protocol !== "https:") {
        return new Response(null, { status: 308, headers: { Location: `https://${url.host}${url.pathname}` } });
      }
      if (url.pathname.startsWith("/api/")) return await api(request, url.pathname);
      if (url.pathname === "/" && request.method === "GET") {
        const nonce = token(18);
        const h = secureHeaders(nonce);
        h.set("Content-Type", "text/html; charset=utf-8");
        return new Response(page(nonce), { headers: h });
      }
      return new Response("Page not found.", { status: 404, headers: secureHeaders() });
    } catch {
      return new Response("We could not complete that request. Please try again.", { status: 500, headers: secureHeaders() });
    }
  },
});

console.log("MFA enrolment server listening securely on https://localhost:3000");
